from typing import Annotated
from fastapi import Cookie, FastAPI

app = FastAPI()

@app.get("/session")
async def read_session(session_id: Annotated[str | None, Cookie()] = None) -> dict[str, str | None]:
    return {"session_id": session_id}

from typing import Annotated
from fastapi import FastAPI, Header

app = FastAPI()

@app.get("/agent")
async def read_agent(user_agent: Annotated[str | None, Header()] = None) -> dict[str, str | None]:
    return {"user_agent": user_agent}

from typing import Annotated
from fastapi import FastAPI, Form

app = FastAPI()

@app.post("/login")
async def login(username: Annotated[str, Form()], password: Annotated[str, Form()]) -> dict[str, str]:
    return {"username": username, "password_length": str(len(password))}

from fastapi import FastAPI, UploadFile

app = FastAPI()

@app.post("/files")
async def upload(file: UploadFile) -> dict[str, object]:
    content = await file.read()
    return {"filename": file.filename, "content_type": file.content_type, "size": len(content)}
